public class SpeakerDispatchTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            SpeakerDispatch child = new SpeakerDispatch();
            Speaker asBase = child;
            Speaker plain = new Speaker();

            check("greet is overridden", "HELLO", child.greet());
            check("override wins through a base reference", "HELLO", asBase.greet());
            check("the base class itself is unchanged", "hello", plain.greet());

            check("declared type SpeakerDispatch picks the String overload",
                    "Dispatch/String:hi", child.announce("hi"));
            check("declared type Speaker picks announce(Object), overridden",
                    "Dispatch/Object:hi", asBase.announce("hi"));
            check("an explicit cast changes which method is compiled in",
                    "Dispatch/Object:hi", ((Speaker) child).announce("hi"));
            check("a non-String argument has only one candidate",
                    "Dispatch/Object:42", child.announce(Integer.valueOf(42)));

            check("route declares Object, so the overload is invisible there",
                    "Dispatch/Object:hi", SpeakerDispatch.route(child, "hi"));
            check("route on a plain Speaker", "Speaker/Object:hi",
                    SpeakerDispatch.route(plain, "hi"));

            Object asObject = "hi";
            check("a String held in an Object variable also picks announce(Object)",
                    "Dispatch/Object:hi", child.announce(asObject));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

