/** Provided -- do not edit. */
class Speaker {

    public String announce(Object item) {
        return "Speaker/Object:" + item;
    }

    public String greet() {
        return "hello";
    }
}

public class SpeakerDispatch extends Speaker {

    @Override
    public String greet() {
        return "HELLO";
    }

    @Override
    public String announce(Object item) {
        return "Dispatch/Object:" + item;
    }

    public String announce(String item) {
        return "Dispatch/String:" + item;
    }

    public static String route(Speaker speaker, Object value) {
        return speaker.announce(value);
    }
}
